// Test-only harness: random programs in the subset, run in Bun (or Node) and in the trusted model
// (`ariadne batch`). Wherever the model gives a value, JavaScript must give the same one; the model may
// fault instead (behaviour it does not model), never disagree. Programs are generated by type so that
// most of them run to a value, over numbers near the safe-integer limits, strings with surrogates,
// arrays and their callbacks, records, `switch`, and loops with `break` and `continue`.
import { writeFile, mkdtemp } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import { resolve, join } from 'node:path';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';
import { observe } from './observe.mjs';

const cli = resolve('.lake/build/bin/ariadne');
let seed = Number(process.env.FUZZ_SEED ?? 0x51ed2701);
const random = () => ((seed = (Math.imul(seed ^ (seed >>> 15), 0x2c1b3c6d) + 0x6d2b79f5) >>> 0) / 2 ** 32);
const pick = xs => xs[Math.floor(random() * xs.length)];
const chance = p => random() < p;

const numLits = ['0', '1', '2', '3', '7', '10', '-1', '-7', '9007199254740991', '-9007199254740991', '4503599627370496', '100'];
const strLits = ['""', '"a"', '"b"', '"ab"', '"ba"', '"abc"', '"\\uD83D\\uDE00"', '"\\uD800"', '"é"', '"A"', '"a\\u0000"', '"zz"'];

/** A program's state while generating: variables in scope by type, and how deep we are. */
class Scope {
  constructor(vars = []) { this.vars = vars; }
  of(t) { return this.vars.filter(v => v.t === t).map(v => v.name); }
  with(name, t, mutable) { return new Scope([...this.vars, { name, t, mutable }]); }
}

let fresh = 0;
const name = p => `${p}${fresh++}`;

function num(s, d) {
  const vs = s.of('number');
  if (d <= 0 || chance(0.25)) return vs.length && chance(0.6) ? pick(vs) : pick(numLits);
  switch (Math.floor(random() * 12)) {
    case 0: return `(${num(s, d - 1)} + ${num(s, d - 1)})`;
    case 1: return `(${num(s, d - 1)} - ${num(s, d - 1)})`;
    case 2: return `(${num(s, d - 1)} * ${num(s, d - 1)})`;
    case 3: return `(${num(s, d - 1)} % ${num(s, d - 1)})`;
    case 4: return `Math.floor(${num(s, d - 1)} / ${num(s, d - 1)})`;
    case 5: return `-(${num(s, d - 1)})`;
    case 6: return `${str(s, d - 1)}.length`;
    case 7: return `${arr(s, d - 1)}.length`;
    case 8: return `${str(s, d - 1)}.indexOf(${str(s, d - 1)})`;
    case 9: return `(${bool(s, d - 1)} ? ${num(s, d - 1)} : ${num(s, d - 1)})`;
    case 10: return `(${arr(s, d - 1)}[${num(s, d - 1)}] ?? ${num(s, d - 1)})`;
    default: return `(${rec(s, d - 1)}).n`;
  }
}

function str(s, d) {
  const vs = s.of('string');
  if (d <= 0 || chance(0.3)) return vs.length && chance(0.6) ? pick(vs) : pick(strLits);
  switch (Math.floor(random() * 5)) {
    case 0: return `(${str(s, d - 1)} + ${str(s, d - 1)})`;
    case 1: return `${str(s, d - 1)}.slice(${num(s, d - 1)})`;
    case 2: return `${str(s, d - 1)}.slice(${num(s, d - 1)}, ${num(s, d - 1)})`;
    case 3: return `(${bool(s, d - 1)} ? ${str(s, d - 1)} : ${str(s, d - 1)})`;
    default: return `(${rec(s, d - 1)}).s`;
  }
}

function bool(s, d) {
  const vs = s.of('boolean');
  if (d <= 0 || chance(0.2)) return vs.length && chance(0.5) ? pick(vs) : pick(['true', 'false']);
  switch (Math.floor(random() * 12)) {
    case 0: return `(${num(s, d - 1)} ${pick(['<', '<=', '>', '>=', '===', '!=='])} ${num(s, d - 1)})`;
    case 1: return `(${str(s, d - 1)} ${pick(['<', '<=', '>', '>=', '===', '!=='])} ${str(s, d - 1)})`;
    case 2: return `!${bool(s, d - 1)}`;
    case 3: return `(${bool(s, d - 1)} && ${bool(s, d - 1)})`;
    case 4: return `(${bool(s, d - 1)} || ${bool(s, d - 1)})`;
    case 5: return `${str(s, d - 1)}.${pick(['startsWith', 'endsWith', 'includes'])}(${str(s, d - 1)})`;
    case 6: return `${arr(s, d - 1)}.includes(${num(s, d - 1)})`;
    case 7: { const y = name('y'); return `${arr(s, d - 1)}.${pick(['some', 'every'])}((${y}) => ${bool(s.with(y, 'number'), d - 1)})`; }
    case 8: return `(${arr(s, d - 1)}[${num(s, d - 1)}] === undefined)`;
    case 9: return `(${arr(s, d - 1)}[${num(s, d - 1)}] == null)`;
    case 10: return `(${bool(s, d - 1)} === ${bool(s, d - 1)})`;
    default: return `(${rec(s, d - 1)}).b`;
  }
}

function arr(s, d) {
  const vs = s.of('number[]');
  if (d <= 0 || chance(0.25)) {
    if (vs.length && chance(0.6)) return pick(vs);
    return `[${Array.from({ length: Math.floor(random() * 4) }, () => num(s, 0)).join(', ')}]`;
  }
  const y = name('y');
  const z = name('z');
  switch (Math.floor(random() * 6)) {
    case 0: return `[${num(s, d - 1)}, ...${arr(s, d - 1)}, ${num(s, d - 1)}]`;
    case 1: return `${arr(s, d - 1)}.filter((${y}) => ${bool(s.with(y, 'number'), d - 1)})`;
    case 2: return `${arr(s, d - 1)}.map((${y}) => ${num(s.with(y, 'number'), d - 1)})`;
    case 3: return `${arr(s, d - 1)}.toSorted((${y}, ${z}) => ${pick([`${y} - ${z}`, `${z} - ${y}`, `(${y} % 3) - (${z} % 3)`])})`;
    case 4: return `(${bool(s, d - 1)} ? ${arr(s, d - 1)} : ${arr(s, d - 1)})`;
    default: return `[${str(s, d - 1)}.length]`;
  }
}

function rec(s, d) {
  const vs = s.of('rec');
  if (vs.length && chance(0.5)) return pick(vs);
  if (d <= 0 || chance(0.5)) return `{ n: ${num(s, 0)}, s: ${str(s, 0)}, b: ${bool(s, 0)} }`;
  return recUpdate(s, d - 1);
}

/** A field update keeping the field's type. */
function recUpdate(s, d) {
  const f = pick(['n', 's', 'b']);
  const v = f === 'n' ? num(s, d) : f === 's' ? str(s, d) : bool(s, d);
  return `{ ...${rec(s, d)}, ${f}: ${v} }`;
}

const typed = { number: num, string: str, boolean: bool, 'number[]': arr, rec: (s, d) => (chance(0.5) ? rec(s, d) : recUpdate(s, d)) };

/** Statements; `inLoop` allows break/continue. Returns [lines, scope]. */
function stmts(s, depth, n, inLoop, ind) {
  const out = [];
  for (let k = 0; k < n; k++) {
    const r = Math.floor(random() * 10);
    if (r <= 2) {
      const t = pick(Object.keys(typed));
      const x = name('v');
      out.push(`${ind}let ${x} = ${typed[t](s, 2)};`);
      s = s.with(x, t, true);
    } else if (r === 3) {
      const ms = s.vars.filter(v => v.mutable);
      if (ms.length) { const v = pick(ms); out.push(`${ind}${v.name} = ${typed[v.t](s, 2)};`); }
    } else if (r === 4 && depth > 0) {
      out.push(`${ind}if (${bool(s, 2)}) {`, ...stmts(s, depth - 1, 2, inLoop, ind + '  ')[0], `${ind}} else {`,
        ...stmts(s, depth - 1, 2, inLoop, ind + '  ')[0], `${ind}}`);
    } else if (r === 5 && depth > 0) {
      const x = name('x');
      out.push(`${ind}for (const ${x} of ${arr(s, 2)}) {`, ...stmts(s.with(x, 'number', false), depth - 1, 3, true, ind + '  ')[0], `${ind}}`);
    } else if (r === 6 && depth > 0) {
      const i = name('i');
      out.push(`${ind}let ${i} = 0;`, `${ind}while (${i} < ${pick(['0', '1', '3', '5'])}) {`, `${ind}  ${i}++;`,
        ...stmts(s.with(i, 'number', false), depth - 1, 2, true, ind + '  ')[0], `${ind}}`);
      s = s.with(i, 'number', false);
    } else if (r === 7 && depth > 0) {
      const e = str(s, 1);
      out.push(`${ind}switch (${e}) {`);
      for (const l of [pick(strLits), pick(strLits)]) {
        out.push(`${ind}  case ${l}:`, ...stmts(s, depth - 1, 1, inLoop, ind + '    ')[0]);
        if (chance(0.7)) out.push(`${ind}    break;`);
      }
      out.push(`${ind}  default:`, ...stmts(s, depth - 1, 1, inLoop, ind + '    ')[0], `${ind}}`);
    } else if (r === 8 && inLoop && chance(0.5)) {
      out.push(`${ind}if (${bool(s, 1)}) ${pick(['break', 'continue'])};`);
    } else if (r === 9 && chance(0.3)) {
      out.push(`${ind}if (${bool(s, 1)}) return ${observable(s)};`);
    }
  }
  return [out, s];
}

const observable = s => `[${num(s, 2)}, ${str(s, 2)}, ${bool(s, 1)}, ${arr(s, 1)}]`;

function program(count) {
  const fns = [];
  for (let k = 0; k < count; k++) {
    fresh = 0;
    const [lines, s] = stmts(new Scope(), 2, 5, false, '  ');
    fns.push(`export function t_${k}(): number {\n${lines.join('\n')}\n  return ${observable(s)};\n}`);
  }
  return fns.join('\n\n') + '\n';
}

const dir = await mkdtemp(join(tmpdir(), 'ariadne-fuzz-'));
const files = Number(process.env.FUZZ_FILES ?? 60);
const perFile = 25;
let agreed = 0, refused = 0, failures = 0, rejected = 0;
for (let f = 0; f < files; f++) {
  const path = join(dir, `p${f}.ts`);
  await writeFile(path, program(perFile));
  const names = Array.from({ length: perFile }, (_, k) => `t_${k}`);
  const run = spawnSync(cli, ['batch', path], { input: names.map(n => JSON.stringify([n])).join('\n') + '\n', encoding: 'utf8' });
  if (run.status !== 0) { rejected++; if (rejected <= 3) console.error(`${path}: ${run.stderr.split('\n')[0]}`); continue; }
  const results = run.stdout.trim().split('\n').map(l => JSON.parse(l));
  const module = await import(pathToFileURL(path).href);
  names.forEach((n, i) => {
    const model = results[i];
    if (model[0] === 'error') { refused++; return; }
    let js;
    try { js = observe(module[n]()); } catch (e) { js = ['throws', String(e)]; }
    if (JSON.stringify(js) === JSON.stringify(model)) { agreed++; return; }
    failures++;
    console.error(`${path}:${n}\n  js    ${JSON.stringify(js)}\n  model ${JSON.stringify(model)}`);
  });
}
if (failures > 0) { console.error(`Model fuzzing: ${failures} disagreements.`); process.exit(1); }
if (rejected > 0) { console.error(`Model fuzzing: ${rejected} generated files were not accepted.`); process.exit(1); }
console.log(`Model fuzzing passed: ${agreed} random programs agree with JavaScript (${refused} refused by the model).`);
